function layout(){fit=Math.min(app.screen.width/1824,app.screen.height/864);world.scale.set(fit*zoom);world.position.set((app.screen.width-1824*fit*zoom)/2+pan.x,(app.screen.height-864*fit*zoom)/2+pan.y);}
